-- Muscle Year (GRIZZ, 2026-10-24): "a well scientifically structured muscle
-- building protocol for someone training 3, 4 and 5 days a week. 1 year
-- program, broken into 3 month blocks", with recovery and nutrition managed
-- along the way. Three built-in 52-week programs:
--   3 days: full body A/B/C, Mon/Wed/Fri
--   4 days: upper/lower twice, Mon/Tue/Thu/Fri
--   5 days: upper/lower/push/pull/legs, Mon-Fri
--
-- Four 13-week blocks (52 weeks): 1 Foundation (8-15 reps, 2-3 reps left),
-- 2 Volume (more sets, 1-2 reps left), 3 Strength (main lifts 5-8 reps), 4
-- Peak (8-20 reps, lengthened-position exercises). Exercises change each
-- block; the main lifts stay long enough to progress on.
--
-- Inside each block: rows marked to grow gain a set in weeks 3-4, two in
-- weeks 5-6 and 10-12, one in weeks 8-9 (never over 5 sets). Week 7 is a
-- deload and week 13 a review week, both at half the sets, so there is an
-- easy week every 6 weeks (deload_check counts them, so the trainer isn't
-- told to add another). Each muscle gets about 10-20 hard sets a week,
-- trained twice or more a week (Schoenfeld 2016/2017 frequency and volume
-- meta-analyses; Pelland 2024; Bell 2023 deload consensus).
--
-- No overhead pressing (GRIZZ's rule for built-ins) and no hack squats;
-- single-leg work in every block. Every exercise is already in the library.
-- The helper upserts row by row, so this file can be re-run safely.


create or replace function public.add_muscle_year(p_name text, p_description text, p_nutrition text, p_warm_up text, p_titles jsonb, p_tpl jsonb)
returns void
language plpgsql
set search_path = public
as $f$
declare
  prog uuid;
  titles text[] := '{}';
  -- Extra sets on the rows marked to grow, for weeks 1-13 of a block.
  extra int[] := array[0, 0, 1, 1, 2, 2, 0, 1, 1, 2, 2, 2, 0];
  w int;
  k int;
  bw int;
  dd int;
  bk text;
  half boolean;
  tag text;
  d text;
  r jsonb;
  i int;
  n int;
begin
  for w in 1..52 loop
    k := (w - 1) / 13 + 1;
    bw := w - (k - 1) * 13;
    tag := case bw when 7 then ' (deload week)' when 13 then ' (review week)' else '' end;
    for dd in 1..7 loop
      titles := titles || case when p_titles ? dd::text
        then 'Block ' || k || ': ' || (p_titles ->> dd::text) || tag
        else 'Rest and recover' end;
    end loop;
  end loop;
  select id into prog from public.programs where trainer_id is null and name = p_name limit 1;
  if prog is null then
    insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
    values (null, p_name, 'weekly', 'gym', 52, p_description, p_nutrition, p_warm_up, titles)
    returning id into prog;
  else
    update public.programs set weeks = 52, description = p_description, nutrition = p_nutrition, warm_up = p_warm_up, day_titles = titles
    where id = prog;
  end if;
  for w in 1..52 loop
    k := (w - 1) / 13 + 1;
    bw := w - (k - 1) * 13;
    bk := 'b' || k;
    half := bw in (7, 13);
    for d in select jsonb_object_keys(p_tpl -> bk) loop
      i := 0;
      for r in select * from jsonb_array_elements(p_tpl -> bk -> d) loop
        i := i + 1;
        n := (r->>1)::int;
        n := case when half then greatest(1, ceil(n / 2.0)::int)
                  when (r->>4)::boolean then least(5, n + extra[bw])
                  else n end;
        update public.program_exercises
        set exercise_id = (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            exercise_name = r->>0, sets = n, reps = r->>2, rest_seconds = (r->>3)::smallint, kind = 'exercise'
        where program_id = prog and week_number = w and day_number = d::smallint and sort_order = i;
        if not found then
          insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
          values (prog, w, d::smallint, i,
            (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            r->>0, n, r->>2, (r->>3)::smallint, 'exercise');
        end if;
      end loop;
      if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.week_number = w
                 and pe.day_number = d::smallint and pe.sort_order > i) then
        raise exception '% week % day % has more rows than the template', p_name, w, d;
      end if;
    end loop;
  end loop;
  if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.exercise_id is null) then
    raise exception 'an exercise in % is not in the library', p_name;
  end if;
end $f$;
revoke all on function public.add_muscle_year(text, text, text, text, jsonb, jsonb) from public, anon, authenticated;

select public.add_muscle_year('Muscle Year – 3 days a week', 'A 1-year muscle building program for 3 days a week (full body on Monday, Wednesday and Friday). It''s built on the muscle research: each muscle is trained about twice a week, with 10-20 hard sets per muscle a week, sets taken close to failure and the weight going up whenever you hit the top of the rep range. It runs in four 3-month blocks of 13 weeks:
Block 1 (weeks 1-13), Foundation: learn every lift and build the habit. Moderate weights for 8-15 reps, stopping each set with 2-3 good reps left.
Block 2 (weeks 14-26), Volume: more sets for each muscle, 8-15 reps, stopping with 1-2 reps left. This is where most of the new muscle comes from.
Block 3 (weeks 27-39), Strength: heavier main lifts for 5-8 reps with longer rests, so you can lift more in block 4. Other exercises stay at 8-12 reps.
Block 4 (weeks 40-52), Peak: back to 8-20 reps, with exercises that stretch the muscle under load (incline curls, overhead extensions, deep leg presses). The last set of the small exercises can go to 1 rep short of failure.
Inside each block, sets go up on the main exercises in weeks 3 and 5 and again from week 10. Week 7 is a deload (half the sets, about 70% of the weight) and week 13 is a review week (half the sets: check your best weights, weigh in, take progress photos and recover before the next block). With 3 sessions, every session is full body, so you train every muscle 3 times a week and get a rest day between sessions. Keep your form clean: add weight only when every rep in every set is done well. Can''t do a chin-up yet? Do it on the assisted pull-up machine. Recovery is part of the program: sleep 7-9 hours, take at least one full rest day a week, and use the Recovery section on your rest days. If your joints ache, you''re tired for days, or your lifts go down two sessions in a row, tell your coach so a deload week can come sooner.', 'Muscle is built from food. Work out your numbers in Nutrition > Muscle building: your BMR and macros: your BMR (what your body burns at rest), what you burn in a day with training, and your daily calories and macros. In short: eat about 5-10% more than your body uses (around 200-350 kcal a day), protein 1.6-2.2 g per kg of bodyweight split over 3-5 meals with 25-40 g each, fat at least 0.8 g per kg, and the rest from carbs (rice, potatoes, sweet potato, pap, bread, fruit, beans). Put most of your carbs in the meals before and after training. Weigh in every 2 weeks: aim to gain about 0.25-0.5% of your bodyweight a week (about 1-2 kg a month for most people). Gaining faster than that is mostly fat, so eat a bit less; not gaining, eat a bit more. Keep eating normally in deload and review weeks. Drink 35 ml of water per kg a day plus extra around training.', '5-8 minute warm-up: 3-4 minutes easy bike, rower or walk, then leg swings, hip circles, band pull-aparts and arm circles. Before the first exercise of the day, do 2-3 lighter ramp-up sets (about 50%, 70% and 85% of your working weight) before your working sets.', '{"1": "Full body A", "3": "Full body B", "5": "Full body C"}'::jsonb, '{"b1":{"1":[["Barbell Back Squat",3,"8-12",150,true],["Flat Dumbbell Press",3,"8-12",90,true],["Seated Cable Row",3,"10-12",90,true],["Romanian Deadlift",3,"10-12",120,false],["Dumbbell Lateral Raise",3,"12-15",60,false],["Dumbbell Curl",2,"12-15",60,false],["Cable Rope Pushdown",2,"12-15",60,false]],"3":[["Leg Press",3,"10-15",120,true],["Lat Pulldown",3,"10-12",90,true],["Incline Dumbbell Press",3,"10-12",90,true],["Seated Leg Curl",3,"10-15",60,false],["Reverse Pec Deck",2,"12-15",60,false],["Standing Calf Raise",3,"10-15",60,false],["Plank",2,"30-45 sec",45,false]],"5":[["Dumbbell Bulgarian Split Squat",3,"10-12 each leg",90,true],["Machine Chest Press",3,"10-12",90,true],["Chest-Supported Row",3,"10-12",90,true],["Hip Thrust",3,"10-12",90,false],["Machine Lateral Raise",2,"12-15",60,false],["Hammer Curl",2,"10-12",60,false],["Overhead Cable Extension",2,"12-15",60,false]]},"b2":{"1":[["Barbell Back Squat",3,"8-10",150,true],["Incline Barbell Press",3,"8-12",120,true],["Barbell Bent-Over Row",3,"8-12",120,true],["Seated Leg Curl",3,"10-12",75,false],["Leaning Cable Lateral Raise",3,"12-15",60,false],["Incline Dumbbell Curl",3,"10-12",60,false],["Overhead Cable Extension",3,"10-12",60,false]],"3":[["Romanian Deadlift",3,"8-10",150,true],["Flat Dumbbell Press",3,"8-12",90,true],["Neutral-Grip Lat Pulldown",3,"10-12",90,true],["Walking Lunge",3,"10-12 each leg",90,false],["Cable Bar Face Pull",3,"12-15",60,false],["Seated Calf Raise",3,"12-15",60,false],["Hanging Knee Raise",2,"10-15",60,false]],"5":[["Leg Press",3,"10-12",120,true],["Chest-Supported T-Bar Row",3,"8-12",90,true],["Dumbbell Bulgarian Split Squat",3,"8-12 each leg",90,true],["Cable Fly",3,"12-15",60,false],["Dumbbell Lateral Raise",3,"12-15",60,false],["Cable Curl",2,"10-12",60,false],["Cable Rope Pushdown",2,"10-12",60,false]]},"b3":{"1":[["Barbell Back Squat",4,"5-8",180,true],["Bench Press",4,"5-8",180,true],["Pendlay Row",4,"6-8",150,true],["Seated Leg Curl",3,"8-12",75,false],["Dumbbell Lateral Raise",3,"10-15",60,false],["EZ-Bar Curl",2,"8-10",60,false]],"3":[["Trap Bar Deadlift",3,"5-6",180,false],["Incline Dumbbell Press",3,"6-10",120,true],["Lat Pulldown",3,"6-10",120,true],["Dumbbell Bulgarian Split Squat",3,"8-10 each leg",90,true],["Reverse Pec Deck",3,"12-15",60,false],["Standing Calf Raise",3,"8-12",60,false]],"5":[["Leg Press",3,"8-10",150,true],["Close-Grip Bench Press",3,"6-8",120,true],["Seated Cable Row",3,"8-10",90,true],["Hip Thrust",3,"6-10",120,false],["Machine Lateral Raise",2,"12-15",60,false],["Hammer Curl",2,"8-12",60,false],["Skull Crusher",2,"8-12",60,false]]},"b4":{"1":[["Barbell Back Squat",3,"6-10",150,true],["Incline Dumbbell Press",3,"8-12",120,true],["Dumbbell Single-Arm Row",3,"10-12 each arm",90,true],["Seated Leg Curl",3,"10-15",75,false],["Cable Low Single-Arm Lateral Raise",3,"12-20 each arm",45,false],["Bayesian Curl",3,"12-15 each arm",60,false],["Single-Arm Overhead Cable Extension",2,"12-15 each arm",60,false]],"3":[["Romanian Deadlift",3,"8-10",150,true],["Machine Chest Press",3,"10-12",90,true],["Wide-Grip Lat Pulldown",3,"10-12",90,true],["Front-Foot-Elevated Split Squat",3,"10-12 each leg",90,false],["Machine Face Pull",3,"15-20",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Kneeling Cable Crunch",2,"12-15",60,false]],"5":[["Leg Press",3,"12-15",120,true],["Cable Low-to-High Fly",3,"12-15",60,true],["Chest-Supported Row",3,"10-12",90,true],["Leg Extension",3,"12-20",60,false],["Leaning Cable Lateral Raise",3,"12-20",45,false],["Incline Dumbbell Curl",2,"10-15",60,false],["Cable Rope Pushdown",2,"12-15",60,false]]}}'::jsonb);
select public.add_muscle_year('Muscle Year – 4 days a week', 'A 1-year muscle building program for 4 days a week (upper body and lower body, twice each: Monday, Tuesday, Thursday and Friday). It''s built on the muscle research: each muscle is trained about twice a week, with 10-20 hard sets per muscle a week, sets taken close to failure and the weight going up whenever you hit the top of the rep range. It runs in four 3-month blocks of 13 weeks:
Block 1 (weeks 1-13), Foundation: learn every lift and build the habit. Moderate weights for 8-15 reps, stopping each set with 2-3 good reps left.
Block 2 (weeks 14-26), Volume: more sets for each muscle, 8-15 reps, stopping with 1-2 reps left. This is where most of the new muscle comes from.
Block 3 (weeks 27-39), Strength: heavier main lifts for 5-8 reps with longer rests, so you can lift more in block 4. Other exercises stay at 8-12 reps.
Block 4 (weeks 40-52), Peak: back to 8-20 reps, with exercises that stretch the muscle under load (incline curls, overhead extensions, deep leg presses). The last set of the small exercises can go to 1 rep short of failure.
